init_media_library_service();
async function publicStudio(db, slug2) {
  const row = await db.prepare("SELECT s.published,s.revision FROM ProductStudio s JOIN Product p ON p.id=s.productId WHERE p.slug=? AND p.status='ACTIVE' AND p.deletedAt IS NULL AND s.published IS NOT NULL").bind(slug2).first();
  if (!row) throw new MediaError("Kh\xF4ng t\xECm th\u1EA5y s\u1EA3n ph\u1EA9m \u0111\xE3 xu\u1EA5t b\u1EA3n.", 404);
  const d2 = JSON.parse(row.published);
  const media = [];
  for (const m2 of d2.media) {
    const { asset } = await mediaDetail(db, m2.assetId);
    media.push({ url: asset.url, kind: asset.kind, alt: m2.alt, variantId: m2.variantId });
  }
  return { ...d2, media, canOrder: ["AVAILABLE", "PREORDER"].includes(d2.availability) };
}

// src/server/services/storefront-cms.service.ts
async function classifyProductPublication(identifier, optionsOrDb) {
  const options = optionsOrDb && "prepare" in optionsOrDb ? { lookupType: "auto", explicitDb: optionsOrDb } : optionsOrDb || { lookupType: "auto" };
  const db = options.explicitDb || (await mediaEnvironment()).DB;
  const lookupType = options.lookupType || "auto";
  let query;
  let params;
  if (lookupType === "id") {
    query = `SELECT
        p.id,
        p.slug,
        p.status AS productStatus,
        p.deletedAt,
        s.productId AS studioProductId,
        s.published AS studioPublished,
        s.revision AS studioRevision
      FROM Product p
      LEFT JOIN ProductStudio s ON s.productId = p.id
      WHERE p.id = ?
      LIMIT 1`;
    params = [identifier];
  } else if (lookupType === "slug") {
    query = `SELECT
        p.id,
        p.slug,
        p.status AS productStatus,
        p.deletedAt,
        s.productId AS studioProductId,
        s.published AS studioPublished,
        s.revision AS studioRevision
      FROM Product p
      LEFT JOIN ProductStudio s ON s.productId = p.id
      WHERE p.slug = ?
      LIMIT 1`;
    params = [identifier];
  } else {
    query = `SELECT
        p.id,
        p.slug,
        p.status AS productStatus,
        p.deletedAt,
        s.productId AS studioProductId,
        s.published AS studioPublished,
        s.revision AS studioRevision
      FROM Product p
      LEFT JOIN ProductStudio s ON s.productId = p.id
      WHERE (p.slug = ? OR p.id = ?)
      ORDER BY CASE WHEN p.slug = ? THEN 0 ELSE 1 END
      LIMIT 1`;
    params = [identifier, identifier, identifier];
  }
  const stmt = db.prepare(query);
  const bound = params.length === 1 ? stmt.bind(params[0]) : stmt.bind(params[0], params[1], params[2]);
  const row = await bound.first();
  if (!row) {
    return { kind: "NOT_FOUND" };
  }
  if (row.deletedAt !== null) {
    return { kind: "DELETED" };
  }
  const isProductActive = ["ACTIVE", "active"].includes(row.productStatus);
  if (row.studioProductId !== null) {
    const revision = row.studioRevision ?? 0;
    if (!row.studioPublished) {
      return {
        kind: "CMS_NOT_PUBLIC",
        productId: row.id,
        slug: row.slug,
        revision,
        reason: "DRAFT_OR_UNPUBLISHED"
      };
    }
    if (!isProductActive) {
      return {
        kind: "CMS_NOT_PUBLIC",
        productId: row.id,
        slug: row.slug,
        revision,
        reason: "INACTIVE_STATUS"
      };
    }
    return {
      kind: "CMS_PUBLISHED",
      productId: row.id,
      slug: row.slug,
      revision
    };
  }
  if (isProductActive) {
    return { kind: "LEGACY_ACTIVE", productId: row.id, slug: row.slug };
  }
  return {
    kind: "LEGACY_INACTIVE",
    productId: row.id,
    slug: row.slug,
    status: row.productStatus
  };
}
